mapper.select:
SELECT a.program_id , b.program_name , a.system_service_id , a.system_service_desc , NVL(a.control_flag,'Y') AS use_flag FROM LGCOM_PROGRAM_SERVICE_N a , LGCOM_PROGRAM_M b WHERE a.program_id = b.program_id
AND a.program_id = #{programId}
AND b.program_name LIKE #{programName} || '%'
AND a.control_flag = #{useFlag}
ORDER BY a.program_id, a.system_service_id

SELECT COUNT(program_id) AS cnt
  FROM LGCOM_PROGRAM_SERVICE_N
 WHERE program_id        = #{programId}
   AND system_service_id = #{systemServiceId}

mapper.update:
UPDATE LGCOM_PROGRAM_SERVICE_N
   SET system_service_desc = #{systemServiceDesc}
     , control_flag        = NVL(#{useFlag},'Y')
     , last_updated_by     = #{sessionUserId}
     , last_update_date    = SYSDATE
 WHERE program_id          = #{programId}
   AND system_service_id   = #{systemServiceId}

UPDATE LGCOM_PROGRAM_SERVICE_N
   SET control_flag      = 'N'
     , last_updated_by   = #{sessionUserId}
     , last_update_date  = SYSDATE
 WHERE program_id        = #{programId}
   AND system_service_id = #{systemServiceId}

mapper.delete:
DELETE FROM LGCOM_PROGRAM_ACCESS_N
      WHERE program_id        = #{programId}
        AND system_service_id = #{systemServiceId}
        AND role_code         = #{roleCode}
